import { defineSchema, lazySchema } from "../../../src/schemas/index.js";
import { generateCommandSchema, generateSchema } from "../../commands/schema/command.js";
import { VERSION } from "../../utils/index.js";
const getSchemaInput = lazySchema(defineSchema((v) => v.object({
    command: v.string().optional().describe("Get schema for a specific command"),
    category: v.string().optional().describe("Filter by category"),
})));
const vfGetSchema = {
    name: "vf_get_schema",
    title: "Get CLI Schema",
    annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
    description: "Use this when you need to discover available CLI commands, their arguments, and flags. Returns the command schema as JSON. Do not use for project info. Use vf_get_project_info instead.",
    inputSchema: getSchemaInput,
    execute: async (input) => {
        if (input.command) {
            return generateCommandSchema(input.command) ?? { error: `Unknown command: ${input.command}` };
        }
        return generateSchema(input.category);
    },
};
const getProjectInfoInput = lazySchema(defineSchema((v) => v.object({})));
const vfGetProjectInfo = {
    name: "vf_get_project_info",
    title: "Get Project Info",
    annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
    description: "Use this when you need project metadata including project slug, version, and environment. Returns slug, version, and environment config. Do not use for CLI commands. Use vf_get_schema instead.",
    inputSchema: getProjectInfoInput,
    execute: async () => {
        const { getEnvironmentConfig } = await import("../../../src/config/index.js");
        const config = getEnvironmentConfig();
        return {
            version: VERSION,
            projectSlug: config.projectSlug ?? null,
            nodeEnv: config.nodeEnv,
            veryfrontEnv: config.veryfrontEnv,
        };
    },
};
export const introspectionTools = [
    vfGetSchema,
    vfGetProjectInfo,
];
